"""Original liver disease in pregnancy questions."""
from qbank_authoring import question,ref,finalize
PR=ref('EASL 2023 Liver Diseases in Pregnancy Guideline','https://easlcampus.eu/sites/default/files/2023-07/EASL%20CPG%20management%20of%20liver%20diseases%20in%20pregnancy.pdf')
AA=ref('AASLD Reproductive Health and Liver Disease Guidance','https://doi.org/10.1002/hep.31559')
SM=ref('SMFM Consult 53: Intrahepatic Cholestasis of Pregnancy','https://cdn.smfm.org.s3.amazonaws.com/attachments/876/52ce00b24a640231d1a2130433df7d3d.pdf')
HG=ref('RCOG 2024 Hyperemesis Gravidarum Guideline','https://doi.org/10.1111/1471-0528.17739')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('Which liver-profile changes can be physiological in pregnancy?', 'Increased ALP from placental production and reduced albumin from hemodilution',[
 ('ALT 500 U/L as a routine normal third-trimester change','A substantial aminotransferase rise requires evaluation.'),('INR 2.5 as expected physiology','Prolonged INR is not a normal pregnancy adaptation.'),('Conjugated bilirubin 8 mg/dL as a normal placental effect','Marked hyperbilirubinemia is abnormal.')],
 'Use pregnancy physiology without dismissing real injury', '**ALP and albumin change in ways that can make a standard panel misleading.**', ['Aminotransferases and bilirubin do not normally rise substantially.','GGT or ALP-source assessment can help when the origin is uncertain.'], '**Interpret abnormal values with symptoms and gestational age.**', ['The timing narrows pregnancy-specific diagnoses.','Nonpregnancy causes remain possible throughout gestation.'], [['ALP','Can rise physiologically'],['Albumin','Often lower through dilution'],['ALT/AST/INR/bilirubin','Significant abnormalities need assessment']], [AA,PR])
q('A pregnant patient has ALT 350 U/L. What is the correct general conclusion?', 'Pregnancy alone does not explain this rise; investigate pregnancy-specific and ordinary liver causes',[
 ('All liver tests can rise without limit during pregnancy','This is not physiological.'),('Only HELLP is possible at any gestational age','The differential depends on timing and associated findings.'),('Viral hepatitis is impossible during pregnancy','Pregnancy does not exclude infection.')],
 'An abnormal injury marker deserves an etiological assessment', '**History, medicines, exposures, examination and targeted tests remain central.**', ['Assess blood pressure, platelets, renal function, bilirubin and coagulation when relevant.','Ultrasound is useful for structural questions.'], '**Do not let the pregnancy label delay severe-disease care.**', ['Hypoglycemia, encephalopathy or coagulopathy requires urgent escalation.','Coordinate hepatology and obstetrics.'], [['Early gestation','Hyperemesis among possibilities'],['Later gestation','ICP/HELLP/AFLP among possibilities'],['Any time','Viral, drug, biliary and other causes']], [AA,PR], 'clinical_scenario')
q('At 11 weeks, a patient has severe persistent vomiting, poor intake, weight loss and modest aminotransferase elevation. Other relevant causes are assessed. Which pregnancy-related disorder is most compatible?', 'Hyperemesis gravidarum',[
 ('Typical AFLP','AFLP usually presents in late pregnancy or the early postpartum period.'),('Typical ICP without itch or bile-acid evidence','The clinical syndrome is different.'),('HELLP established solely from vomiting','Hemolysis and platelet/liver findings in the hypertensive spectrum need assessment.')],
 'Gestational timing is a diagnostic clue', '**Hyperemesis can be accompanied by liver-test abnormalities.**', ['Evaluate dehydration, electrolytes and nutritional depletion.','Do not use ketonuria alone as a reliable severity measure.'], '**Provide antiemetic, fluid and nutritional care.**', ['Thiamine is important with prolonged poor intake.','Disproportionate injury, persistent jaundice or atypical findings require another cause search.'], [['Early severe vomiting','Hyperemesis concern'],['Late failure phenotype','Consider AFLP/other causes'],['Management','Hydration, antiemetics, nutrition']], [HG,PR], 'clinical_scenario')
q('A patient admitted with prolonged hyperemesis needs dextrose-containing fluids. What preventive step is important?', 'Provide thiamine promptly, especially before carbohydrate loading when feasible',[
 ('No vitamin support is needed if BMI was previously normal','Body size does not exclude depletion.'),('Folate completely substitutes for thiamine','They have different roles.'),('Delay emergency glucose for severe hypoglycemia until a vitamin assay returns','Immediate hypoglycemia treatment must not be withheld.')],
 'Prolonged vomiting can deplete a key carbohydrate-metabolism cofactor', '**Thiamine supplementation helps prevent Wernicke-related complications.**', ['Use an appropriate oral or IV regimen according to intake and clinical suspicion.','Suspected Wernicke disease needs therapeutic parenteral treatment.'], '**Assess the wider refeeding and electrolyte risk.**', ['Potassium, magnesium and phosphate may need monitoring.','Treat hypoglycemia immediately while arranging vitamin replacement.'], [['Thiamine','Before/with feeding when feasible'],['Severe hypoglycemia','Do not delay rescue'],['Refeeding','Electrolyte monitoring']], [HG], 'clinical_scenario')
q('At 32 weeks, itching is most prominent on the palms and soles without a primary rash. Bile acids are elevated. What diagnosis is favored?', 'Intrahepatic cholestasis of pregnancy',[
 ('AFLP as the best fit solely from itch','AFLP is typically a systemic liver-failure phenotype.'),('HELLP solely from itching without the relevant blood findings','The defining hemolytic/platelet pattern is absent.'),('Gilbert syndrome','This does not explain the characteristic pruritic bile-acid syndrome.')],
 'Pruritus can precede other obvious liver abnormalities', '**ICP is a pregnancy-associated cholestatic syndrome diagnosed using symptoms and bile-acid elevation after excluding alternatives.**', ['Nonfasting thresholds and local definitions should be applied consistently.','A normal initial result may require repeat testing if characteristic itching persists.'], '**Assess fetal risk using the appropriate marker.**', ['Bile-acid severity is more informative for fetal risk than ALT magnitude alone.','Plan care with obstetrics and monitor for other diagnoses.'], [['Symptoms','Pruritus without primary rash'],['Biochemistry','Raised bile acids'],['Risk','Peak bile-acid level and other factors']], [PR,SM], 'clinical_scenario')
q('What is the first-line drug for maternal symptoms of ICP under SMFM guidance?', 'Ursodeoxycholic acid',[
 ('Mycophenolate','This is teratogenic and is not the standard ICP drug.'),('Ribavirin','This is not ICP therapy and has reproductive toxicity.'),('Tenofovir','This targets HBV rather than the cholestatic symptom mechanism.')],
 'Treat symptoms without overstating fetal protection', '**UDCA is recommended for maternal symptom relief.**', ['It does not replace bile-acid-based risk assessment and delivery planning.','Pruritus improvement does not guarantee that stillbirth risk has been eliminated.'], '**Keep maternal and fetal goals distinct.**', ['Review response and biochemical course.','Other symptom therapies may be considered by the specialist team if needed.'], [['UDCA','Maternal symptom treatment'],['Bile acids','Risk assessment'],['Delivery plan','Separate essential decision']], [SM,PR])
q('Under SMFM Consult 53, a patient has ICP with bile acids 120 micromol/L. When is delivery offered in the standard recommendation?', 'At 36 weeks, with individual adjustment for other clinical factors',[
 ('At 42 weeks regardless of bile acids','This ignores the increased stillbirth risk in severe ICP.'),('Only after ALT normalizes','ALT is not the principal delivery-risk marker.'),('At 20 weeks in every case','This is not the standard recommendation.')],
 'Name the guidance because exact timing differs between frameworks', '**SMFM uses bile acids at least 100 micromol/L as the severe-risk group for delivery at 36 weeks.**', ['EASL/RCOG frameworks may discuss a 35–36-week window in severe disease.','Additional maternal/fetal risk factors can modify the plan.'], '**Do not use reassuring surveillance to erase bile-acid-associated risk.**', ['Plan antenatal corticosteroids when indicated for delivery before 37 weeks.','Coordinate timing with the obstetric team.'], [['SMFM ≥100','Offer delivery at 36 weeks'],['Lower bile acids','Different timing range'],['Other risks','Individualize']], [SM,PR], 'clinical_scenario')
q('After presumed ICP, pruritus and cholestatic tests persist well into postpartum follow-up. What is the appropriate action?', 'Investigate for an underlying liver or biliary disorder rather than assuming indefinite pregnancy physiology',[
 ('Ignore persistence because ICP never resolves','It usually improves after delivery.'),('Diagnose PBC from itching alone','A proper etiological evaluation is needed.'),('Stop all follow-up after the baby is born','Maternal disease still requires reassessment.')],
 'Resolution after delivery helps validate the pregnancy-specific diagnosis', '**Persistent abnormalities can reveal an autoimmune, viral, structural or transporter-related disorder.**', ['Use an appropriate postpartum repeat-testing interval.','EASL notes usual resolution within three months and investigation if abnormalities persist.'], '**Document the pregnancy episode for future risk counseling.**', ['Recurrence in a later pregnancy is possible.','A new independent liver disease can coexist.'], [['Expected course','Postpartum improvement'],['Persistent abnormality','Evaluate underlying disease'],['Future pregnancy','Recurrence counseling']], [PR], 'clinical_scenario')
q('At 30 weeks, new hypertension accompanies upper abdominal pain, elevated liver enzymes and thrombocytopenia. Which broader obstetric disease spectrum requires urgent assessment?', 'Preeclampsia with severe features/HELLP spectrum',[
 ('Only normal placental ALP production','The hypertensive, platelet and hepatocellular findings are pathological.'),('Gilbert syndrome alone','It does not explain hypertension and thrombocytopenia.'),('Routine uncomplicated hyperemesis as the only diagnosis','The later hypertensive multisystem phenotype is different.')],
 'A liver abnormality can be part of a systemic placental disorder', '**Preeclampsia occurs after 20 weeks and can involve liver and other organs.**', ['Proteinuria is not required in every case when qualifying organ dysfunction is present.','Assess renal, neurological, hematological and fetal status.'], '**Use an urgent obstetric management pathway.**', ['Seizure prevention, blood-pressure control and delivery decisions depend on severity.','Do not manage the liver tests in isolation.'], [['Timing','After 20 weeks'],['Systemic features','Pressure, platelets and organ injury'],['Care','Urgent obstetric multidisciplinary']], [PR,AA], 'clinical_scenario')
q('Which laboratory constellation is most characteristic of HELLP?', 'Hemolysis, elevated liver enzymes and low platelets',[
 ('Isolated bile-acid elevation with normal blood count','This is more compatible with an ICP phenotype.'),('Isolated indirect bilirubin with normal hemoglobin and enzymes','This can fit a benign conjugation disorder.'),('Hyperglycemia with thrombocytosis as a defining triad','This is not the HELLP constellation.')],
 'The acronym captures a microangiopathic multisystem phenotype', '**Look for hemolysis with LDH elevation and appropriate blood-film/biochemical evidence.**', ['Platelet severity and enzyme thresholds depend on the classification used.','The syndrome can occur without a dramatic classic hypertension/proteinuria presentation.'], '**Assess serious hepatic complications.**', ['Severe RUQ pain can signal a hematoma or rupture.','Urgent stabilization and obstetric management are central.'], [['H','Hemolysis'],['EL','Elevated liver enzymes'],['LP','Low platelets']], [PR,AA])
q('A third-trimester patient has jaundice, recurrent hypoglycemia, coagulopathy, renal dysfunction and encephalopathy. Which diagnosis is especially concerning?', 'Acute fatty liver of pregnancy',[
 ('Uncomplicated ICP','ICP does not typically produce this profound metabolic/synthetic failure pattern.'),('Normal late-pregnancy physiology','These are emergency findings.'),('Gilbert syndrome','This cannot explain multisystem liver failure.')],
 'Metabolic and synthetic failure points beyond isolated enzyme injury', '**AFLP often presents late in pregnancy or shortly postpartum.**', ['Hypoglycemia and coagulopathy can help distinguish it from a predominantly HELLP phenotype, although overlap occurs.','Exclude viral, toxic and other acute-failure causes.'], '**Stabilize and expedite obstetric/liver-center care.**', ['Correct glucose and coagulation-related clinical problems as indicated.','Prompt delivery is central once the diagnosis is established.'], [['AFLP','Hypoglycemic synthetic-failure pattern'],['HELLP','Hemolytic/thrombocytopenic pattern'],['Overlap','Possible; urgent care regardless']], [PR,AA], 'clinical_scenario')
q('How are Swansea criteria used in suspected AFLP?', 'Six or more compatible features, in the absence of another explanation, support the diagnosis',[
 ('One isolated ALP rise definitively establishes AFLP','That can be physiological and is insufficient.'),('They replace all differential diagnosis','Several features overlap with other acute liver diseases.'),('A biopsy is mandatory before delivery in every unstable patient','Urgent care should not wait for a hazardous unnecessary procedure.')],
 'A structured feature set supports recognition of a rare emergency', '**The criteria combine symptoms, laboratory abnormalities, imaging and selected histology.**', ['Hypoglycemia, coagulopathy, renal dysfunction and encephalopathy are relevant features.','Specificity is imperfect.'], '**Use the score to support, not postpone, clinical action.**', ['The severity and maternal/fetal state determine urgency.','A competing diagnosis must still be considered.'], [['Threshold','At least 6 compatible features'],['Condition','No better explanation'],['Limitation','Overlap and imperfect specificity']], [PR])
q('What is the central definitive obstetric intervention in AFLP after immediate stabilization?', 'Prompt delivery coordinated by a multidisciplinary team',[
 ('Wait several weeks for ALT to normalize before considering birth','This can prolong the underlying dangerous state.'),('UDCA alone as a substitute for delivery','It does not reverse the acute-failure syndrome.'),('Long-term outpatient observation despite hypoglycemia and encephalopathy','This is unsafe in a critical illness.')],
 'Treat the pregnancy-associated driver while supporting organ failure', '**AFLP is a medical and obstetric emergency.**', ['Correct hypoglycemia, assess bleeding risk and provide renal/critical care when needed.','The safest mode of delivery depends on the obstetric and maternal situation.'], '**Continue monitoring after delivery.**', ['Improvement is not necessarily immediate.','Persistent failure can require liver-center/transplant assessment.'], [['Immediate','Stabilization'],['Definitive obstetric step','Prompt delivery'],['Postpartum','Ongoing organ monitoring']], [PR,AA])
q('Which fetal metabolic defect has a recognized association with maternal AFLP?', 'Long-chain 3-hydroxyacyl-CoA dehydrogenase deficiency',[
 ('HFE C282Y homozygosity as the characteristic fetal defect','This is an iron-loading disorder rather than the classic association.'),('UGT1A1-related Gilbert syndrome','This does not explain the characteristic fatty-acid-oxidation link.'),('ABCC2-related Dubin–Johnson syndrome','This is a bilirubin transport disorder.')],
 'Maternal disease can reveal a fetal fatty-acid-oxidation disorder', '**LCHAD deficiency is an important association, although not every AFLP case has it.**', ['The newborn may be vulnerable to hypoglycemia and other metabolic complications.','Other fatty-acid-oxidation defects can also be relevant.'], '**Arrange neonatal and genetic assessment.**', ['Do not stop care at maternal delivery.','Counsel the family using confirmed findings and recurrence implications.'], [['Maternal syndrome','AFLP'],['Fetal association','LCHAD/other oxidation defects'],['Follow-up','Neonatal metabolic evaluation']], [AA,PR])
q('A patient with HELLP develops sudden severe RUQ/shoulder pain, hypotension and a hemoglobin fall. Which complication must be assessed urgently?', 'Subcapsular hepatic hematoma with possible rupture',[
 ('Simple reflux as the default explanation','The hemodynamic and hematological deterioration is concerning.'),('Benign placental ALP elevation','This cannot explain hemorrhagic shock.'),('An isolated pruritic episode of ICP','That does not fit the bleeding pattern.')],
 'Severe pain can signal a structural hepatic emergency', '**HELLP can cause hepatic hemorrhage, hematoma and rupture.**', ['Urgent imaging should be chosen without delaying resuscitation.','Interventional radiology, surgery and obstetric expertise may be needed.'], '**Treat shock and the underlying obstetric syndrome together.**', ['Blood-product support follows the clinical bleeding problem.','Delivery and definitive hemostasis decisions are coordinated.'], [['Clue','Pain plus shock/Hb fall'],['Concern','Hepatic hematoma/rupture'],['Response','Resuscitation and definitive expertise']], [PR,AA], 'clinical_scenario')
q('A patient with well-controlled AIH delivers a baby. What liver follow-up issue is important in the postpartum period?', 'An increased risk of AIH flare, requiring continued treatment review and biochemical monitoring',[
 ('Delivery permanently cures AIH','The underlying disease persists.'),('Every immunosuppressant must be stopped abruptly at delivery','Abrupt cessation can provoke disease activity.'),('Only newborn monitoring is needed after birth','Maternal disease care remains important.')],
 'Immune changes after pregnancy can alter disease activity', '**Postpartum flares can occur even after a stable pregnancy.**', ['Maintain an appropriate pregnancy/lactation-compatible disease-control plan.','Assess liver tests and IgG according to the specialist schedule.'], '**Balance maternal control and infant safety with accurate drug advice.**', ['Do not assume all medicines have identical lactation restrictions.','Coordinate hepatology and obstetric follow-up.'], [['Pregnancy control','Does not guarantee postpartum stability'],['Monitoring','Liver tests/IgG and symptoms'],['Medication','Supervised continuation/adjustment']], [PR,AA])

